// ---------- (v241, из переделки) табло (Н6): счёт, раунд, таймер, живые — как на трансляции ----------
// Логотипы команд — LINEUP[команда].logo (картинка data:/svg), по сторонам — TEAM_LOGO; пока нет — буква стороны.
// (v304) серия: карта = матч; победитель карты закрашивает свой квадрат. Счёт — по командам (не по сторонам), по номеру матча
// (перемотка того же матча не считает карту дважды). Серия решена — следующий «Сыграть» начинает новую
var SERIES = {bo:3, maps:{}};
function seriesWins(k){ var n = 0; for(var m in SERIES.maps) if(SERIES.maps[m] === k) n++; return n; }
function seriesDone(){ var need = Math.ceil(SERIES.bo/2); return seriesWins("sp") >= need || seriesWins("fa") >= need; }
function seriesUpdate(){
  var need = Math.ceil(SERIES.bo/2);
  ["T","CT"].forEach(function(t){ var el = document.getElementById("sbSer"+t); if(!el) return;
    var k = SIDE_TEAM[t], w = seriesWins(k), h = "";
    for(var i=0;i<need;i++) h += '<i class="'+(i < w ? "w" : "")+'"></i>';
    if(el.dataset.h !== h){ el.dataset.h = h; el.innerHTML = h; } });
  var box = document.getElementById("sbSeries"); if(box) box.style.display = SERIES.bo > 1 ? "" : "none";
}
// (v397, М146) писать в страницу только то, что изменилось: каждая запись (даже того же текста) помечает раскладку страницы
// грязной, и следующее чтение размеров (мини-карта, обсервер — каждый кадр) заставляет браузер пересчитать её целиком
function domText(el, v){ v = String(v); if(el && el.textContent !== v) el.textContent = v; }
function domClass(el, v){ if(el && el.className !== v) el.className = v; }
function domHtml(el, v){ if(el && el._html !== v){ el._html = v; el.innerHTML = v; } }
// (v430) счёт и «живые» выкатываются при смене (hudRoll); полоса под таймером — сколько осталось раунда / фризтайма; бомба — значок C4
var HUD_SB_FRZ = {start:null, len:1};
function scoreboardUpdate(rtLeft){
  seriesUpdate();
  if(typeof paused !== "undefined") hudPaused(paused);
  var $ = function(id){ return document.getElementById(id); };
  ["T","CT"].forEach(function(t){
    var lg = $("sbLogo"+t);
    var src = TEAM_LOGO[t] || "";   // (v270) после смены сторон логотип переезжает вместе с командой
    if(lg.dataset.src !== src){ lg.dataset.src = src; if(src) lg.innerHTML = '<img alt="" src="'+src+'">'; else lg.textContent = t; }
    var nm = $("sbName"+t); if(nm.textContent !== TEAM_NAME[t]){ nm.textContent = TEAM_NAME[t]; nm.title = TEAM_NAME[t]; }
    hudRoll($("sbScore"+t), score[t]);
    hudRoll($("sbAlive"+t), bots.filter(function(b){ return b.team === t && b.alive; }).length);
  });
  domText($("sbMatch"), "матч № "+matchNum);
  if(!WARM.on) domText($("sbRound"), "РАУНД "+Math.max(1, roundNum));
  var tm = $("sbTime"), pg = $("sbProg"), planted = bomb && bomb.state === "planted" && roundState === "live";
  hudBombEdge(planted);
  var prog = function(f, cls){ f = Math.max(0, Math.min(1, f)); f = Math.round(f*500)/500;
    if(pg && pg._f !== f){ pg._f = f; pg.style.transform = "scaleX("+f+")"; } domClass(pg, cls); };
  // бомба стоит — как в CS2: вместо времени раунда значок бомбы (время до взрыва зрители не видят)
  if(planted){ domHtml(tm, hudC4()); domClass(tm, "sb-time bomb"); prog(1, "bomb"); return; }
  if(roundState === "freeze"){ if(HUD_SB_FRZ.start !== roundStartTime){ HUD_SB_FRZ.start = roundStartTime; HUD_SB_FRZ.len = Math.max(1, roundStartTime - simTime); } }
  var sec = roundState === "freeze" ? Math.max(0, roundStartTime - simTime) : rtLeft;
  tm._html = undefined;   // значок бомбы снят — следующий плант нарисует его заново
  if(!WARM.on) domText(tm, Math.floor(sec/60)+":"+("0"+Math.floor(sec%60)).slice(-2));
  var low = roundState === "live" && sec <= 10;
  domClass(tm, "sb-time" + (low ? " low" : ""));
  if(roundState === "freeze") prog(sec/HUD_SB_FRZ.len, "frz");
  else prog(roundState === "live" ? sec/ROUND_TIME_SEC : 0, low ? "low" : "");
  // (v306) разминка: вместо раунда — «РАЗМИНКА · матч в …» и обратный отсчёт до матча
  if(WARM.on){ var wl = Math.max(0, Math.ceil(WARM.left)); domText($("sbRound"), "РАЗМИНКА · матч в "+WARM.match);
    domText(tm, Math.floor(wl/60)+":"+("0"+(wl%60)).slice(-2)); prog(0, ""); }
}

// ---------- панели игроков (Н7): как на трансляции; по центру — выбранный кликом ----------
// Названия — настоящие команды по составу (LINEUP; по сторонам — TEAM_NAME, меняется
// при смене сторон). Фото — PLAYER_PHOTO[ник] (картинка data:/svg); пока нет — серый силуэт.
// (v301) фото игроков — прислал владелец (как в профилях HLTV); белый фон убран, квадрат «голова и плечи» (v303: 192×192 — для карточки по центру)
var PLAYER_PHOTO = {"sh1ro": "data:image/png;base64,", "kyousuke": "data:image/png;base64,", "m0NESY": "data:image/png;base64,", "TeSeS": "data:image/png;base64,", "NiKo": "data:image/png;base64,", "karrigan": "data:image/png;base64,", "donk": "data:image/png;base64,", "zont1x": "data:image/png;base64,", "TN1R": "data:image/png;base64,", "magixx": "data:image/png;base64,"};
var PL_SIL = '<svg viewBox="0 0 40 40"><circle cx="20" cy="14" r="8"/><path d="M4 40c0-9 7-15 16-15s16 6 16 15z"/></svg>';
var PL_ICON = {
  armor:'<svg viewBox="0 0 12 14"><path d="M6 0L12 2.2V7c0 3.6-2.6 6-6 7-3.4-1-6-3.4-6-7V2.2z"/></svg>',
  helmet:'<svg viewBox="0 0 12 14"><path d="M6 0L12 2.2V7c0 3.6-2.6 6-6 7-3.4-1-6-3.4-6-7V2.2z"/><path d="M3.5 4h1.6v2.2h1.8V4h1.6v6H6.9V7.7H5.1V10H3.5z" fill="#222"/></svg>',
  kit:'<svg viewBox="0 0 14 12"><path d="M1 3h3V1h6v2h3v8H1zm4.5-1v1h3V2z"/></svg>',
  smoke:'<svg viewBox="0 0 8 13"><rect x="1" y="2" width="6" height="11" rx="1.5"/><rect x="2.5" y="0" width="3" height="2"/></svg>',
};
// (v290) бомба и гранаты в панелях игроков — иконки CS из набора киллфида (HE, молотов, флешка — владельца; бомба — KF_ICON.C4).
// Остальные (смок, броня, шлем, кит) — пока свои, владелец пришлёт иконки CS
function plKf(key){ var ic = KF_ICON[key]; return ic ? '<svg class="kf" viewBox="'+ic.vb+'">'+ic.svg+'</svg>' : ""; }
PL_ICON.c4 = plKf("C4"); PL_ICON.flash = plKf("flash"); PL_ICON.he = plKf("HE"); PL_ICON.molly = plKf("MOLOTOV");
var plSelected = null;
// (v262) номер — тот же, что в кружке игрока на радаре (pnum)
function plNum(b){ return pnum(b.id); }
function plPhoto(b){ var p = PLAYER_PHOTO[nick(b.id)]; return p ? '<img alt="" src="'+p+'">' : PL_SIL; }
var PL_KILL = '<svg viewBox="0 0 12 12"><path d="M5.3 0h1.4v2.1A4 4 0 0 1 9.9 5.3H12v1.4H9.9a4 4 0 0 1-3.2 3.2V12H5.3V9.9a4 4 0 0 1-3.2-3.2H0V5.3h2.1a4 4 0 0 1 3.2-3.2zM6 3.4a2.6 2.6 0 1 0 0 5.2 2.6 2.6 0 0 0 0-5.2z"/></svg>';
var PL_SKULL = '<svg viewBox="0 0 12 12"><path d="M6 0C2.7 0 .5 2.2.5 5c0 1.7.8 3 2 3.7V11h1.6V9.6h1.1V11h1.6V9.6h1.1V11h1.6V8.7c1.2-.7 2-2 2-3.7C11.5 2.2 9.3 0 6 0zM3.9 4.3a1.3 1.3 0 1 1 0 2.6 1.3 1.3 0 0 1 0-2.6zm4.2 0a1.3 1.3 0 1 1 0 2.6 1.3 1.3 0 0 1 0-2.6z"/></svg>';
// (v323, М28) что у игрока на панели — по порядку закупа: оружие, броня, кит, бомба, гранаты
function plKeys(b){
  // (v397, М145) в руках нож (бег с ножом knifeTick или нечем стрелять) — иконка ножа своей стороны, как в киллфиде (KNIFE / KNIFE_T)
  var knife = b._knife || !b.weapon, wkey = knife ? (b.team === "T" ? "KNIFE_T" : "KNIFE") : b.weapon.key;
  var L = [], ic = typeof KF_ICON !== "undefined" && KF_ICON ? KF_ICON[wkey] : {vb:"", svg:""};   // до загрузки иконок (первый закуп) — только ключи
  var I = (typeof PL_ICON !== "undefined" && PL_ICON) || {};
  if(ic) L.push({key:"w:"+wkey, w:true, wk:wkey, html:'<svg class="wp" viewBox="'+ic.vb+'">'+ic.svg+'</svg>'});
  if(b.helmet) L.push({key:"helmet", html:I.helmet}); else if(b.armor) L.push({key:"armor", html:I.armor});
  if(b.team === "CT" && b.kit) L.push({key:"kit", html:I.kit});
  if(b.team === "T" && typeof bomb !== "undefined" && bomb && bomb.state === "carried" && bomb.carrier === b) L.push({key:"c4", html:I.c4});
  var N = b.nades || {}; ["smoke","flash","he","molly"].forEach(function(k){ for(var i=0;i<(N[k]||0);i++) L.push({key:k+i, html:I[k]}); });
  return L;
}
// (v323, М28) закуп по очереди — только показ: игра покупает в начале фризтайма (решения от этого не меняются), а на панели
// новые вещи появляются по одной. Первая — когда про берут основное оружие (демки Mirage, 25 матчей: 1,05 / 2 / 4,27 / 8,5 /
// 12,9 с от начала фризтайма — 10/25/50/75/90 %), следующие — через BUY_SHOW_GAP (проектное число)
// (v381, М131, владелец 16.10: «панели по бокам не обновляют список оружия после конца раунда для нового») погибший в прошлом раунде
// показывал до своего закупа то оружие, с которым умер (b.weapon после смерти не сбрасывается) — хотя у него уже стартовый пистолет.
// «Что было до закупа» — то, чем игрок владеет (основное, иначе пистолет), а не что было в руках в момент смерти
function buyShowStart(){
  BUY_SHOW = {};
  bots.forEach(function(b, i){
    var own = b.primary || b.secondary || (b.weapon && b.weapon.key) || null;
    var before = {}; plKeys(b).forEach(function(it){ if(!it.w) before[it.key] = true; });
    if(own) before["w:"+own] = own;
    BUY_SHOW[b.id] = {before: before, t0: tick, first: freezePick(BUY_SHOW_FIRST, hashRand(roundNum*733 + i*97 + matchNum*13)), oldW: own};
  });
}
function buyShowHidden(b){
  var S = BUY_SHOW[b.id]; if(!S || roundState !== "freeze") return {};
  var hide = {}, n = 0, el = (tick - S.t0)/TICK_HZ;
  plKeys(b).forEach(function(it){
    if(S.before[it.key] || it.key === "c4") return;   // бомбу не покупают
    if(el < S.first + n*BUY_SHOW_GAP) hide[it.key] = it.w ? (S.oldW || true) : true;
    n++;
  });
  return hide;
}
// (v359, владелец: «неверно отображаются деньги в панелях, либо покупают ганы, не тратя денег») игра покупает всё в начале
// фризтайма, а вещи на панели появляются по одной — деньги же сразу показывались уже после закупа. Теперь деньги на панели
// уменьшаются вместе с появлением вещей: к деньгам прибавлена цена ещё не показанного своего закупа и того, что игрок дропнул
// тиммейту, пока у того вещь не показана. Дроп — у получившего бесплатно (платит дропнувший)
function buyShowMoney(b){
  if(roundState !== "freeze" || !BUY_SHOW[b.id]) return b.money || 0;
  var add = 0, drops = (FREEZE_FX || []).filter(function(f){ return f.kind === "drop"; });
  var price = function(o, it){
    if(it.w){ var dropped = drops.some(function(f){ return f.to === o.id && f.key === it.wk; }); return dropped || !WEAPONS[it.wk] ? 0 : WEAPONS[it.wk].price; }
    if(it.key === "helmet") return BUY_SHOW[o.id].before.armor ? HELMET_UPGRADE : ARMOR_PRICE + HELMET_UPGRADE;
    if(it.key === "armor") return ARMOR_PRICE;
    if(it.key === "kit") return 400;
    var t = it.key.replace(/\d+$/, ""); return NADE[t] ? nadePrice(t, o.team) : 0;
  };
  var hide = buyShowHidden(b);
  plKeys(b).forEach(function(it){ if(hide[it.key]) add += price(b, it); });
  drops.forEach(function(f){ if(f.from !== b.id) return; var o = teamBot(f.to); if(o && buyShowHidden(o)["w:"+f.key] && WEAPONS[f.key]) add += WEAPONS[f.key].price; });
  return (b.money || 0) + add;
}
// (v322, М28) появление купленного на панели игрока: новая вещь (оружие, броня, кит, бомба, граната) — анимация plItIn.
// Панель перерисовывается ~10 раз в секунду, поэтому анимация продолжается с того места, где была (отрицательная задержка)
var PL_SEEN = {}, PL_ANIM_MS = 220;
function plItem(b, key, html){
  var S = PL_SEEN[b.id] || (PL_SEEN[b.id] = {have:{}, now:{}, first:true}), t = performance.now();
  S.now[key] = 1;
  if(!(key in S.have)){ S.have[key] = S.first ? 0 : t;
    // (v338) купил во фризтайм — звук вещи там, где он стоит (оружие / граната; броня и кит — без звука, записей нет)
    var BS = typeof BUY_SHOW !== "undefined" && BUY_SHOW && BUY_SHOW[b.id];
    if(!S.first && roundState === "freeze" && BS && !BS.before[key]) sndPickup(b, /^w:/.test(key) ? "w" : /^(smoke|flash|he|molly)\d/.test(key) ? "nade" : null, true); }
  var age = t - S.have[key];
  return age < PL_ANIM_MS ? '<span class="pl-it new" style="animation-delay:-'+Math.round(age)+'ms">'+html+'</span>' : '<span class="pl-it">'+html+'</span>';
}
function plItemsDone(b){
  var S = PL_SEEN[b.id]; if(!S){ return; }
  for(var k in S.have) if(!S.now[k]) delete S.have[k];   // пропало (бросил, умер) — при новом появлении снова анимация
  S.now = {}; S.first = false;
}
// (v430) панель строится один раз (каркас по составу стороны), дальше меняются только значения — поэтому работают переходы:
// полоса HP и белый «след урона», вспышка при попадании, гаснущая карточка при смерти, «прокрутка» денег и фрагов.
// Раньше панель целиком перестраивалась ~10 раз в секунду (и анимировать было нечего — элементы каждый раз новые)
function plSkel(ids){
  return '<div class="pl-tag"></div>' + ids.map(function(id){
    return '<div class="pl-card" data-id="'+id+'" tabindex="0" title="Показать игрока"><div class="pl-hit"></div>'+
      '<div class="pl-num"></div>'+
      '<div class="pl-body"><div class="pl-nick"></div>'+
        '<div class="pl-stat"><span>'+PL_KILL+'<i class="pk"></i></span><span>'+PL_SKULL+'<i class="pd"></i></span><span class="pl-money">$<i class="pm"></i></span></div></div>'+
      '<div class="pl-ava"></div>'+
      '<div class="pl-side"><div class="pl-top"><span class="pl-wp"></span><span class="pl-hp"></span></div><div class="pl-gear"></div></div>'+
      '<div class="pl-bar"><b class="tr"></b><b class="hp"></b></div></div>';
  }).join("");
}
var PL_MONEY = function(v){ return v.toLocaleString("en-US"); };
function plCardUpdate(c, b){
  var q = function(s){ return c.querySelector(s); };
  var R = c._r || (c._r = {num:q(".pl-num"), nick:q(".pl-nick"), k:q(".pk"), d:q(".pd"), m:q(".pm"), ava:q(".pl-ava"), wp:q(".pl-wp"),
    hp:q(".pl-hp"), gear:q(".pl-gear"), tr:q(".pl-bar .tr"), hb:q(".pl-bar .hp"), hit:q(".pl-hit")});
  var hp = b.alive ? Math.max(0, Math.round(b.hp)) : 0, low = hp > 0 && hp <= 25;
  domClass(c, "pl-card" + (b.alive ? "" : " dead") + (plSelected === b.id ? " sel" : "") + (low ? " low" : ""));
  domText(R.num, plNum(b));
  domText(R.nick, nick(b.id));
  hudNum(R.k, b.kills || 0); hudNum(R.d, b.deaths || 0); hudNum(R.m, buyShowMoney(b), PL_MONEY);
  if(R.ava._id !== nick(b.id)){ R.ava._id = nick(b.id); R.ava.innerHTML = plPhoto(b); }   // (док 6) фото — по нику: после смены сторон тот же слот у другого игрока
  var wp = "", gear = "";
  if(b.alive){
    var hide = buyShowHidden(b);
    plKeys(b).forEach(function(it){
      if(hide[it.key]){ if(it.w && hide[it.key] !== true){ var ic0 = KF_ICON[hide[it.key]]; if(ic0) wp = '<span class="pl-it"><svg class="wp" viewBox="'+ic0.vb+'">'+ic0.svg+'</svg></span>'; } return; }
      if(it.w) wp = plItem(b, it.key, it.html); else gear += plItem(b, it.key, it.html);
    });
  }
  plItemsDone(b);
  domHtml(R.wp, wp); domHtml(R.gear, gear);
  domHtml(R.hp, b.alive ? String(hp) : PL_SKULL);
  // HP: полоса сразу, «след» — с задержкой (CSS); стало меньше — красная вспышка, умер — вспышка дольше
  var f = hp/100;
  if(R.f !== f){
    var tr = "scaleX("+f+")";
    if(R.f === undefined || f > R.f){ R.tr.style.transition = "none"; R.tr.style.transform = tr; R.hb.style.transform = tr; }
    else { R.tr.style.transition = ""; R.tr.style.transform = tr; R.hb.style.transform = tr; }
    if(R.f !== undefined && f < R.f && R.alive !== false)
      hudAnim(R.hit, [{opacity:b.alive ? .9 : 1}, {opacity:0}], {duration:b.alive ? 520 : 1100, easing:"cubic-bezier(.2,.8,.2,1)"});
    R.f = f;
  }
  if(R.alive === true && !b.alive) hudAnim(c, [{transform:"translateX("+(b.team === "T" ? "-" : "")+"6px)"}, {transform:"none"}], {duration:320, easing:"cubic-bezier(.2,.8,.2,1)"});
  R.alive = b.alive;
}
function playersUpdate(){
  ["T","CT"].forEach(function(t){
    var el = document.getElementById("pl"+t); if(!el) return;
    var mates = bots.filter(function(b){ return b.team === t; }), key = mates.map(function(b){ return b.id; }).join(",");
    if(el._key !== key){ el._key = key; el.innerHTML = plSkel(mates.map(function(b){ return b.id; })); el._cards = el.querySelectorAll(".pl-card"); el._tag = el.querySelector(".pl-tag"); }
    domText(el._tag, TEAM_NAME[t]);
    mates.forEach(function(b, i){ plCardUpdate(el._cards[i], b); });
  });
  var f = document.getElementById("plFocus"), b = plSelected && teamBot(plSelected);
  if(!b || !b.alive){ plSelected = null; domClass(f, ""); var ph0 = document.getElementById("pfPhoto"); if(ph0) ph0.dataset.id = ""; return; }
  var cls = "show "+b.team.toLowerCase()+(f.classList.contains("pop") ? " pop" : ""); if(f.className !== cls) f.className = cls;
  var ph = document.getElementById("pfPhoto"); if(ph.dataset.id !== nick(b.id)){ ph.dataset.id = nick(b.id); ph.innerHTML = plPhoto(b); f.classList.remove("pop"); void f.offsetWidth; f.classList.add("pop"); }   // (v303) новая карточка — анимация заново
  domText(document.getElementById("pfNick"), nick(b.id));
  var php = Math.max(0, Math.round(b.hp));
  domText(document.getElementById("pfHp"), php);
  if(f._hp !== php){ f._hp = php; f.style.setProperty("--hp", String(php/100)); }
  domHtml(document.getElementById("pfKd"), (b.kills||0)+'<i></i>'+(b.deaths||0));
}
// клик по строке игрока в панели — его карточка; повторный клик — убрать
["plT","plCT"].forEach(function(id){
  var el = document.getElementById(id); if(!el) return;
  var pick = function(e){ var c = e.target.closest && e.target.closest(".pl-card"); if(!c) return;
    var bb = teamBot(c.dataset.id); plSelected = (plSelected === c.dataset.id || !bb || !bb.alive) ? null : c.dataset.id; playersUpdate(); };
  el.addEventListener("pointerdown", function(e){ if(e.button === 0) pick(e); });   // не click: строки перерисовываются ~10 раз в секунду
  el.addEventListener("keydown", function(e){ if(e.key === "Enter" || e.key === " "){ e.preventDefault(); pick(e); } });
});
// клик по игроку на радаре (не перетаскивание камеры) — он в центре; мимо — убрать
(function(){
  var down = null;
  cv.addEventListener("mousedown", function(e){ if(e.button === 0) down = {x:e.clientX, y:e.clientY}; });
  cv.addEventListener("mouseup", function(e){
    if(e.button !== 0 || !down || Math.hypot(e.clientX-down.x, e.clientY-down.y) > 4){ down = null; return; }
    down = null;
    var w = navScreenToWorld(e.clientX, e.clientY), best = null, bd = 16/view.scale;
    bots.forEach(function(b){ if(!b.alive) return; var d = Math.hypot(b.x-w.x, b.y-w.y); if(d < bd){ bd = d; best = b; } });
    plSelected = best ? best.id : null;
    playersUpdate();
  });
})();

